{'content': '// Planetary Gearbox - Print-in-Place
// Designed for PETG, 0.4mm nozzle, 0.1-0.2mm layer height
// Features: Herringbone gears (self-capturing), Captive Carrier, Floating Planets

/* [Dimensions] */
// Height of the gears
gear_h = 10;
// Module (Tooth size)
mod = 1.0;
// Number of teeth
t_sun = 15;
t_planet = 9;
t_ring = 33; // t_sun + 2*t_planet
// Clearance between moving parts (Critical for PETG)
tol = 0.30; 

/* [Rendering] */
$fn = 64;

// Derived Dimensions
p_sun = t_sun * mod / 2;     // Pitch Radius
p_planet = t_planet * mod / 2;
p_ring = t_ring * mod / 2;
dist = p_sun + p_planet;     // Center distance

twist_angle = 30; // Herringbone twist amount

// Main Assembly
module assembly() {
    // 1. Sun Gear (Center)
    // Includes a base flange to capture the Carrier
    color("Gold") 
    union() {
        // Upper Gear part
        translate([0,0,2]) 
        gear_herringbone(t_sun, p_sun, gear_h, twist_angle, -1);

        // Lower Shaft / Core
        translate([0,0,0])
        cylinder(r=p_sun - 1.5, h=gear_h+2);

        // Bottom Capture Flange (Locks Carrier vertically)
        // Chamfered to allow printing
        cylinder(r1=p_sun+1, r2=p_sun-1, h=2);

        // Input Drive (Hex Socket)
        translate([0,0,gear_h-3])
        cylinder(r=3, h=6, $fn=6);
    }

    // 2. Ring Gear (Outer)
    color("Silver")
    translate([0,0,2]) // Lifted to match gear plane
    difference() {
        union() {
            // Main Housing
            cylinder(r=p_ring + 3, h=gear_h);
            // Knurling/Grips
            for(i=[0:30:360]) rotate([0,0,i]) translate([p_ring+3,0,0]) cylinder(r=0.8, h=gear_h);
        }
        // Internal Gear Teeth
        gear_herringbone(t_ring, p_ring, gear_h, twist_angle, 1, internal=true);
    }

    // 3. Carrier (Bottom Plate + Pins)
    // Sits on build plate (Z=0), captured by Sun Flange and Gear Mesh
    color("Red")
    difference() {
        union() {
            // Base Plate
            linear_extrude(2)
            difference() {
                // Tri-lobe shape connecting the pins
                hull() {
                    for(i=[0:120:359]) {
                        rotate([0,0,i]) translate([dist, 0, 0]) circle(r=p_planet-1.5);
                    }
                    circle(r=p_sun + 1.5);
                }
            }

            // Pins for Planets
            for(i=[0:120:359]) {
                rotate([0,0,i]) translate([dist, 0, 2]) {
                    // Shaft
                    cylinder(r=p_planet/2 - tol, h=gear_h-1);
                    // Top Cap to capture planet (Chamfered)
                    translate([0,0,gear_h-1]) cylinder(r1=p_planet/2 - tol, r2=p_planet/2 + 1, h=1); 
                }
            }
        }

        // Center Clearance for Sun (with Tolerance)
        translate([0,0,-1]) cylinder(r=p_sun + tol, h=15);

        // Clearance cuts for Ring Gear (so carrier doesn't fuse to ring base if any)
        // (Ring starts at Z=2, so Z=0..2 is safe if diameter is small enough)
         difference() {
            translate([0,0,-1]) cylinder(r=p_ring*2, h=5);
            cylinder(r=p_ring - 0.5, h=5); // Keep inner area
        }
    }

    // 4. Planet Gears
    // Floating, supported by mesh with Sun/Ring
    color("Cyan")
    for(i=[0:120:359]) {
        rotate([0,0,i]) translate([dist, 0, 2.2]) { // 0.2mm Z-gap above Carrier
            difference() {
                gear_herringbone(t_planet, p_planet, gear_h - 0.4, -twist_angle, 1); // Slightly shorter to clear caps

                // Bore Hole for Carrier Pin
                // Includes chamfers for printability
                union() {
                    cylinder(r=p_planet/2 + tol, h=gear_h + 1, center=true);
                    // Top Chamfer to match Pin Cap
                    translate([0,0,gear_h - 1.4]) cylinder(r1=p_planet/2+tol, r2=p_planet/2+tol+1.5, h=1.5);
                    // Bottom Chamfer for bridge capability over Carrier Check
                    translate([0,0,0]) cylinder(r1=p_planet/2+tol+1, r2=p_planet/2+tol, h=1);
                }
            }
        }
    }
}

// --- Gear Generation Modules ---

module gear_herringbone(number_of_teeth, pitch_radius, height, twist, direction, internal=false) {
    // Halves for herringbone
    h_half = height / 2;

    translate([0,0,0])
    union() {
        // Bottom half
        linear_extrude(height=h_half, twist=direction * twist, slices=15)
        gear_2d(number_of_teeth, pitch_radius, internal);

        // Top half
        translate([0,0,h_half])
        linear_extrude(height=h_half, twist=direction * -twist, slices=15)
        gear_2d(number_of_teeth, pitch_radius, internal);
    }
}

module gear_2d(N, R, internal=false) {
    // Simplified Involute-like Profile for Robust Printing
    // Uses a Trapezoidal approximation which is much faster and cleaner for FDM
    // Tolerance is applied here by offsetting the radius

    // Tooth dimensions
    P = R * 2 * PI / N; // Circular Pitch
    addendum = mod;
    dedendum = 1.2 * mod;

    eff_R = internal ? R + tol/2 : R - tol/2;

    // Generate simplified tooth profile polygon
    // Just the outline of one tooth, repeated N times

    tooth_width_ang = 360 / (2 * N);

    difference() {
        if (internal) {
            circle(r=R + 10); // Housing
        } else {
            circle(r=eff_R + addendum);
        }

        if (internal) {
             // For internal gears, we subtract the teeth form
             // But actually, it's easier to union teeth for external, subtract for internal
             // Let's do the cutout method for internal
             for (i=[0:N-1]) {
                 rotate([0,0,i*360/N])
                 translate([eff_R, 0, 0])
                 // Shape of the slot between teeth
                 basic_tooth_cutout(mod, tol);
             }
             circle(r=eff_R - addendum);
        } else {
            // Cut voids between teeth
             for (i=[0:N-1]) {
                 rotate([0,0,i*360/N + 360/(2*N)]) // Offset half pitch
                 translate([eff_R, 0, 0])
                 basic_tooth_cutout(mod, -tol); // Negative tolerance makes teeth thinner
             }
        }
    }
}

module basic_tooth_cutout(m, tolerance) {
     // Trapezoidal groove
     // Width at pitch line ~ PI*m/2
     width = PI*m/2 + (tolerance); // Widen cutout = Thinner tooth
     depth = 2.25 * m;

     translate([0, 0]) 
     polygon(points=[
        [m, -width/2 - m*0.3], // Base wide
        [m, width/2 + m*0.3],
        [-depth/2, width/2], 
        [-depth, width/2 - m*0.3], // Tip narrow
        [-depth, -width/2 + m*0.3],
        [-depth/2, -width/2]
     ]);
}

assembly();
'}

{'content': '// Planetary Gearbox - Print-in-Place (Revised)
// Designed for PETG, 0.4mm nozzle, 0.2mm layer height
// Features: Herringbone gears, Captive Carrier, Floating Planets supported by Gear Mesh

/* [Dimensions] */
gear_height = 10;
module_val = 1.0;
number_teeth_sun = 15;
number_teeth_planet = 9; 
number_teeth_ring = 33; // Must be Sun + 2*Planet

// Clearances
tol = 0.25; // General xy clearance
z_gap = 0.25; // Vertical clearance for non-fusing

/* [Rendering] */
$fn = 60;

// Derived
pitch_sun = (number_teeth_sun * module_val) / 2;
pitch_planet = (number_teeth_planet * module_val) / 2;
pitch_ring = (number_teeth_ring * module_val) / 2;
distance = pitch_sun + pitch_planet;
twist_val = 200; // Twist amount for herringbone

// Main Assembly
module assembly() {

    // 1. SUN GEAR (Input)
    // Anchored to bed at Center. 
    // Features a bottom flange to trap the Carrier.
    color("Gold")
    union() {
        // Base Flange (Traps Carrier)
        cylinder(r=pitch_sun + module_val, h=1); 
        // Taper up to gear root
        translate([0,0,1]) cylinder(r1=pitch_sun + module_val, r2=pitch_sun - module_val, h=1);

        // The Gear itself
        translate([0,0,0])
        herringbone_gear(number_teeth_sun, pitch_sun, gear_height + 2, twist_val); // +2 to sit on bed

        // Input Hex
        translate([0,0,gear_height+2])
        difference() {
            cylinder(r=pitch_sun-1, h=3);
            cylinder(r=3, h=3.1, $fn=6);
        }
    }

    // 2. RING GEAR (Fixed/Output)
    // Anchored to bed.
    color("Silver")
    translate([0,0,0])
    union() {
        // Outer Shell
        difference() {
            cylinder(r=pitch_ring + 4, h=gear_height + 2);
            translate([0,0,-1]) cylinder(r=pitch_ring + module_val - 0.5, h=gear_height + 4);           
            // Knurling
            for(i=[0:20:360]) rotate([0,0,i]) translate([pitch_ring+4, 0, 0]) cylinder(r=1, h=gear_height+4);
        }
        // The Gear Teeth (Internal)
        herringbone_gear(number_teeth_ring, pitch_ring, gear_height + 2, twist_val, internal=true);
    }

    // 3. PLANET GEARS
    // Floating z_gap above the carrier base?
    // Actually, to print cleanly, they should be supported by the Ring/Sun mesh which starts at Z=0.
    // But we need a Carrier below them?
    // Let's Put Carrier on TOP. It's safer for PIP. No wrapping around the bottom.
    // Revised Strategy: Carrier is a LID. 
    // Pins grow down? No.
    // Stick to Bottom Carrier, but ensure clearances.

    // CARRIER (Bottom)
    color("Red")
    difference() {
        union() {
            // Base Plane (Z=0 to 2)
            // Sits between Sun Flange and Ring
            difference() {
                cylinder(r=pitch_ring - module_val - tol, h=2); // Fits inside Ring
                cylinder(r=pitch_sun + module_val + tol, h=3, center=true); // Fits outside Sun Base
            }
            // Pins
            for(i=[0:120:360]) {
                rotate([0,0,i]) translate([distance, 0, 2]) {
                    cylinder(r=pitch_planet/2 - tol, h=gear_height-1);
                    // Pin Cap (Z=gear_height+1)
                    translate([0,0,gear_height-1]) cylinder(r1=pitch_planet/2-tol, r2=pitch_planet/2+1, h=1.5);
                }
            }
        }
        // Reduce friction surface on base
        translate([0,0,0.6]) difference() {
            cylinder(r=pitch_ring-2, h=2);
            cylinder(r=pitch_sun+2, h=2);
        }
    }

    // PLANETS
    // Sit at Z = 2 + z_gap. 
    // Supported by mesh with Sun/Ring (which are solid from Z=0).
    color("Cyan")
    for(i=[0:120:360]) {
        rotate([0,0,i]) translate([distance, 0, 2 + z_gap]) {
            difference() {
                // Gear Body
                herringbone_gear(number_teeth_planet, pitch_planet, gear_height - z_gap, -twist_val);

                // Bore
                cylinder(r=pitch_planet/2 + tol*1.5, h=gear_height+2, center=true);

                // Chamfer for Pin Cap Clearance
                translate([0,0, gear_height - z_gap - 1.5]) cylinder(r1=pitch_planet/2+tol, r2=pitch_planet/2+tol+2, h=2);
            }
            // Add a bottom chanfer effectively reducing the overhang contact
             difference() {
                 cylinder(r=pitch_planet-1, h=0.4);
                 cylinder(r=pitch_planet-4, h=1);
             }
        }
    }

}

// --- Helpers ---

module herringbone_gear(N, R, h, twist, internal=false) {
    // Splits into two twisted halves

    // Involute Tooth Profile Calculation
    pitch = (2 * PI * R) / N;
    tooth_base_w = pitch / 2;

    // We create a single tooth polygon and rotate it
    module single_tooth_2d() {
         polygon(points=[
            [-tooth_base_w/2, -module_val],
            [-tooth_base_w/4, module_val],
            [tooth_base_w/4, module_val],
            [tooth_base_w/2, -module_val]
        ]);
    }

    // More accurate Involute approximation
    module gear_shape_2d() {
        union() {
            circle(r= R - module_val + (internal?2:0));
            for(i=[0:N-1]) {
                rotate([0,0,i*360/N]) translate([0, R, 0])
                if (internal) {
                     // Internal: Subtract teeth from a disk?
                     // Handled in parent.
                } else {
                     polygon([
                        [-5*PI/N, -1.2], 
                        [-2*PI/N, 1.2],
                        [2*PI/N, 1.2],
                        [5*PI/N, -1.2]
                     ]); // Very Rough
                }
            }
        }
    }

    // Let's use a verified trapezoidal gear generator for reliability
    module trap_gear_2d() {
        difference() {
            if (internal) {
                circle(r=R + 5);
            } else {
                circle(r=R + module_val - (internal?0:tol/2));
            }

            if (internal) {
                // For internal, we cut the teeth out of the disk
                for(i=[0:N-1]) rotate([0,0,i*360/N]) translate([0,R,0]) 
                    // Cutout shape
                    polygon([
                        [-1.6*module_val, -module_val], 
                        [-0.7*module_val, 1.2*module_val], 
                        [0.7*module_val, 1.2*module_val], 
                        [1.6*module_val, -module_val]
                    ]);
                cylinder(r=R - module_val + tol/2, $fn=N*2);
            } else {
                // For external, we cut valleys
                for(i=[0:N-1]) rotate([0,0,i*360/N + 180/N]) translate([0,R,0]) 
                    polygon([
                        [-1.6*module_val, module_val*1.4], 
                        [-0.6*module_val, -module_val], 
                        [0.6*module_val, -module_val], 
                        [1.6*module_val, module_val*1.4]
                    ]);
            }
        }
    }

    translate([0,0,0])
    union() {
        linear_extrude(height=h/2, twist=twist, slices=20) trap_gear_2d();
        translate([0,0,h/2])
        linear_extrude(height=h/2, twist=-twist, slices=20) trap_gear_2d();
    }
}

assembly();
'}

{'content': '// Planetary Gearbox - Print-in-Place (Final Revised)
// Designed for PETG, 0.4mm nozzle, 0.2mm layer height

/* [Dimensions] */
// Height of the gears (Active gear area)
gear_height = 10;
// Height of the base/carrier structure
base_height = 2;
// Module (Tooth size)
module_val = 1.0;
// Helix Angle (keep < 45 for printing). Determine twist.
helix_angle = 35; 

// Teeth
t_sun = 15;
t_planet = 9;
t_ring = 33; 

// Tolerances
tol = 0.25; // Radial clearance
z_gap = 0.25; // Vertical clearance

/* [Rendering] */
$fn = 64;

// Derived
p_sun = t_sun * module_val / 2;
p_planet = t_planet * module_val / 2;
p_ring = t_ring * module_val / 2;
dist = p_sun + p_planet;

// Twist Math
// twist_deg = (H * tan(helix) * 180) / (PI * R)
function calc_twist(R, H) = (H * tan(helix_angle) * 180) / (PI * R);

// Calculate specific twists
twist_sun = calc_twist(p_sun, gear_height);
twist_planet = calc_twist(p_planet, gear_height); 
twist_ring = calc_twist(p_ring, gear_height);

// Global V-shape split position (Halfway up the gear stack)
split_pos = gear_height / 2;

module assembly() {

    // 1. SUN GEAR (Input)
    // Anchored at Z=0 (actually Z=base_height for gear part)
    color("Gold")
    union() {
        // Base - Captive mechanism
        cylinder(r1=p_sun + module_val + 1, r2=p_sun + module_val, h=base_height); 

        // Gear
        translate([0,0,base_height])
        herringbone_gear_custom(t_sun, p_sun, gear_height, twist_sun, split_pos);

        // Cap/Handle
        translate([0,0,base_height + gear_height])
        cylinder(r=p_sun*0.8, h=3);
    }

    // 2. RING GEAR (Output/Fixed)
    color("Silver")
    union() {
        // Base Rim (Anchors Ring to bed)
        cylinder(r=p_ring + 3, h=base_height);

        // Gear Housing
        translate([0,0,base_height])
        difference() {
            cylinder(r=p_ring + 3, h=gear_height);
            // Internal Teeth
            herringbone_gear_custom(t_ring, p_ring, gear_height, twist_ring, split_pos, internal=true);
        }
    }

    // 3. CARRIER (Fixed to Bed - Cage Style)
    // Sits at Z=0. Pins go up.
    color("Red")
    difference() {
        union() {
            cylinder(r=p_ring - module_val - tol, h=base_height); // Base Disk
            // Pins
            for(i=[0:120:359]) rotate([0,0,i]) translate([dist,0,base_height]) {
                 cylinder(r=p_planet/2 - tol, h=gear_height - z_gap);
                 // Cap on pin
                 translate([0,0,gear_height - z_gap]) cylinder(r1=p_planet/2 - tol, r2=p_planet/2 + 1, h=1.5);
            }
        }
        // Hollow out center for Sun Base
        translate([0,0,-1]) cylinder(r=p_sun + module_val + tol, h=base_height+2);

        // Relief cuts for friction reduction
        translate([0,0,0.6]) difference() {
             cylinder(r=p_ring - 2, h=5);
             cylinder(r=p_sun + 2, h=5);
        }
    }

    // 4. PLANETS (Floating)
    // Start at Z = base_height + z_gap
    // Height = gear_height - 2*z_gap
    // Must verify Twist Phase and Split alignment
    color("Cyan")
    for(i=[0:120:359]) rotate([0,0,i]) translate([dist, 0, base_height + z_gap]) {
        // Phase Correction:
        // We are lifting the gear by z_gap RELATIVE TO THE SUN/RING START (which is base_height)
        // Wait, Sun starts at base_height. Ring starts at base_height.
        // Planet starts at base_height + z_gap.
        // Offset = z_gap.
        // Rotation needed = twist_per_mm * z_gap
        // Twist Rate (deg/mm) = twist_planet / gear_height.
        // Direction: Planet is opposite to Sun. 
        // Sun has twist+. Planet has twist-.
        // To match Sun at Z_local=z_gap, Planet must be rotated.

        // Actually, easiest way: generate full gear, slice intersection.
        intersection() {
            // Generates a planet aligned with Sun at Z=base_height
            herringbone_gear_custom(t_planet, p_planet, gear_height, -twist_planet, split_pos);

            // Cut to size
            translate([0,0,0]) cylinder(r=p_planet+module_val, h=gear_height - 2*z_gap);
        }

        // Wait, the intersection method puts the bottom of the planet at Z=0 local.
        // But we want to print it at Z=base_height + z_gap.
        // We moved the origin to [dist, 0, base_height + z_gap].
        // So we need to generate negative Z geometry?
        // No. 
        // We need: geometry that fits into the Sun's shape at Z_global = base + z_gap.
        // Sun Shape at Global Z = base+z_gap corresponds to Sun Local Z = z_gap.
        // Planet Shape at its Local Z=0 must match Sun Local Z=z_gap.
        // Planet Local Z=0 corresponds to Helix Phase (twist/H)*z_gap.
        // So Rotate Planet by (twist/H)*z_gap.

        rotate([0,0, (-twist_planet/gear_height) * z_gap ])
        difference() {
            herringbone_gear_custom(t_planet, p_planet, gear_height - 2*z_gap, -twist_planet, split_pos - z_gap);

            // Bore
            cylinder(r=p_planet/2 + tol*1.5, h=gear_height+2, center=true);

            // Chamfers
            // Top Cap Clearance
            translate([0,0, gear_height - 2*z_gap - 1.5]) cylinder(r1=p_planet/2+tol, r2=p_planet/2+tol+2, h=2);
            // Bottom printing chamfer
            cylinder(r1=p_planet - 2, r2=p_planet, h=1); 
        }
    }
}

// Custom Herringbone Module with Split Control
module herringbone_gear_custom(N, R, h, total_twist, split_z_local, internal=false) {
    // split_z_local: The height at which the helix flips (relative to bottom of this part)
    // For fixed gears, this is gear_height/2.
    // For floating planet, this is (gear_height/2) - z_offset.

    // Twist rates
    rate = total_twist / h; // deg per mm

    // Bottom Section (0 to split)
    translate([0,0,0])
    linear_extrude(height=split_z_local, twist=rate * split_z_local, slices=20)
    gear_2d_trap(N, R, internal);

    // Top Section (split to h)
    // Start rotation must match end of bottom section
    top_h = h - split_z_local;
    translate([0,0,split_z_local])
    rotate([0,0, rate * split_z_local]) // Align start
    linear_extrude(height=top_h, twist= -rate * top_h, slices=20) // Reverse twist
    gear_2d_trap(N, R, internal);
}

module gear_2d_trap(N, R, internal) {
    // Trapezoidal Gear Profile
    // External: R = Pitch Radius. Addendum = mod. Dedendum = mod.

    if (internal) {
        difference() {
            circle(r=R + 5);
            for(i=[0:N-1]) rotate([0,0,i*360/N]) translate([0,R,0]) 
                polygon([
                    [-1.6*module_val, -module_val], 
                    [-0.7*module_val, 1.25*module_val], 
                    [0.7*module_val, 1.25*module_val], 
                    [1.6*module_val, -module_val]
                ]);
            cylinder(r=R - module_val + tol/2, $fn=N*2);
        }
    } else {
        difference() {
            circle(r=R + module_val - tol/2);
            for(i=[0:N-1]) rotate([0,0,i*360/N + 180/N]) translate([0,R,0]) 
                polygon([
                    [-1.6*module_val, module_val*1.4], 
                    [-0.6*module_val, -module_val], 
                    [0.6*module_val, -module_val], 
                    [1.6*module_val, module_val*1.4]
                ]);
        }
    }
}

assembly();
'}

{'content': '// Planetary Gearbox - Print-in-Place (Final Revised v2)
// Designed for PETG, 0.4mm nozzle, 0.2mm layer height
// Fixes Ring Base overlap issue.

/* [Dimensions] */
// Height of the gears (Active gear area)
gear_height = 10;
// Height of the base/carrier structure
base_height = 2;
// Module (Tooth size)
module_val = 1.0;
// Helix Angle (safe printability)
helix_angle = 35; 

// Teeth
t_sun = 15;
t_planet = 9;
t_ring = 33; 

// Tolerances
tol = 0.25; // Radial clearance
z_gap = 0.25; // Vertical clearance
z_lift = 0.2; // Extra lift for floating parts to aid bridging

/* [Rendering] */
$fn = 64;

// Derived
p_sun = t_sun * module_val / 2;
p_planet = t_planet * module_val / 2;
p_ring = t_ring * module_val / 2;
dist = p_sun + p_planet;

// Twist Math
function calc_twist(R, H) = (H * tan(helix_angle) * 180) / (PI * R);

twist_sun = calc_twist(p_sun, gear_height);
twist_planet = calc_twist(p_planet, gear_height); 
twist_ring = calc_twist(p_ring, gear_height);

// Global V-shape split position (Halfway up the gear stack)
split_pos = gear_height / 2;

module assembly() {

    // 1. SUN GEAR (Input)
    color("Gold")
    union() {
        // Base - Captive mechanism
        cylinder(r1=p_sun + module_val + 1, r2=p_sun + module_val, h=base_height); 

        // Gear
        translate([0,0,base_height])
        herringbone_gear_custom(t_sun, p_sun, gear_height, twist_sun, split_pos);

        // Cap/Handle
        translate([0,0,base_height + gear_height])
        difference() {
             cylinder(r=p_sun*0.8, h=4);
             cylinder(r=3.2, h=5, $fn=6); // Hex Key Hole
        }
    }

    // 2. RING GEAR (Output/Fixed)
    color("Silver")
    union() {
        // Base Rim (Anchors Ring to bed) - NOW HOLLOW
        difference() {
            cylinder(r=p_ring + 3, h=base_height);
            translate([0,0,-1]) cylinder(r=p_ring - module_val + tol*2, h=base_height+2);
        }

        // Gear Housing
        translate([0,0,base_height])
        difference() {
            cylinder(r=p_ring + 3, h=gear_height);
            // Internal Teeth
            herringbone_gear_custom(t_ring, p_ring, gear_height, twist_ring, split_pos, internal=true);

            // Knurling
            for(i=[0:15:359]) rotate([0,0,i]) translate([p_ring+3,0,0]) cylinder(r=0.7, h=gear_height+1, center=true);
        }
    }

    // 3. CARRIER (Fixed to Bed - Cage Style)
    color("Red")
    difference() {
        union() {
            // Base Disk
            cylinder(r=p_ring - module_val - tol, h=base_height); 
            // Pins
            for(i=[0:120:359]) rotate([0,0,i]) translate([dist,0,base_height]) {
                 cylinder(r=p_planet/2 - tol, h=gear_height - z_gap);
                 // Cap on pin (Captive top)
                 translate([0,0,gear_height - z_gap]) cylinder(r1=p_planet/2 - tol, r2=p_planet/2 + 1.2, h=1.5);
            }
        }
        // Hollow out center for Sun Base
        translate([0,0,-1]) cylinder(r=p_sun + module_val + tol, h=base_height+2);

        // Relief cuts for friction reduction
        translate([0,0,0.6]) difference() {
             cylinder(r=p_ring - 2, h=5);
             cylinder(r=p_sun + 2, h=5);
        }
    }

    // 4. PLANETS (Floating)
    color("Cyan")
    for(i=[0:120:359]) rotate([0,0,i]) translate([dist, 0, base_height + z_gap]) {
        // Phase Correction Logic
        rotate([0,0, (-twist_planet/gear_height) * z_gap ])
        difference() {
            herringbone_gear_custom(t_planet, p_planet, gear_height - 2*z_gap, -twist_planet, split_pos - z_gap);

            // Bore
            cylinder(r=p_planet/2 + tol*1.5, h=gear_height+2, center=true);

            // Chamfers
            // Top Cap Clearance
            translate([0,0, gear_height - 2*z_gap - 1.5]) cylinder(r1=p_planet/2+tol, r2=p_planet/2+tol+2.5, h=2);
            // Bottom printing chamfer (Overhang minimizer)
            difference() {
                cylinder(r=p_planet, h=0.8);
                cylinder(r=p_planet-1.5, h=1);
            }
        }
    }
}

// Custom Herringbone Module with Split Control
module herringbone_gear_custom(N, R, h, total_twist, split_z_local, internal=false) {
    rate = total_twist / h; 

    // Bottom Section
    translate([0,0,0])
    linear_extrude(height=split_z_local, twist=rate * split_z_local, slices=25)
    gear_2d_trap(N, R, internal);

    // Top Section
    top_h = h - split_z_local;
    translate([0,0,split_z_local])
    rotate([0,0, rate * split_z_local]) 
    linear_extrude(height=top_h, twist= -rate * top_h, slices=25) 
    gear_2d_trap(N, R, internal);
}

module gear_2d_trap(N, R, internal) {
    // Trapezoidal Gear Profile
    if (internal) {
        difference() {
            circle(r=R + 5);
            for(i=[0:N-1]) rotate([0,0,i*360/N]) translate([0,R,0]) 
                polygon([
                    [-1.6*module_val, -module_val], 
                    [-0.7*module_val, 1.25*module_val], 
                    [0.7*module_val, 1.25*module_val], 
                    [1.6*module_val, -module_val]
                ]);
            cylinder(r=R - module_val + tol/2, $fn=N*2);
        }
    } else {
        difference() {
            circle(r=R + module_val - tol/2);
            for(i=[0:N-1]) rotate([0,0,i*360/N + 180/N]) translate([0,R,0]) 
                polygon([
                    [-1.6*module_val, module_val*1.4], 
                    [-0.6*module_val, -module_val], 
                    [0.6*module_val, -module_val], 
                    [1.6*module_val, module_val*1.4]
                ]);
        }
    }
}

